"""Emits ui/components/RigData.kt (layer boxes in rig units) from work/rig-art/rig.json."""
import json
P='/workspace/projects/63d46980-7164-4457-910d-060f812d1fca'
r=json.load(open(f'{P}/work/rig-art/rig.json'))
L=r['layers']
out=['package com.wakil.agent.ui.components','','import com.wakil.agent.R','',
'/** Generated by scripts/assets-gen/robot_rig_kotlin.py from the rig cut (rig units = px of the 1024² front art). */',
'internal class RigBox(val res: Int, val x: Int, val y: Int, val w: Int, val h: Int)','',
'internal object RigData {']
for k,v in L.items():
    out.append(f'    val {k} = RigBox(R.drawable.{v["file"]}, {v["x"]}, {v["y"]}, {v["w"]}, {v["h"]})')
pv=r['pivots']
for k,(x,y) in pv.items():
    out.append(f'    const val {k.upper()}_X = {x}f; const val {k.upper()}_Y = {y}f')
out.append(f'    const val MIRROR_X = {r["mirrorX"]}f')
for k,(x,y) in r['lens'].items():
    out.append(f'    const val LENS_{k.upper()}_X = {x:.1f}f; const val LENS_{k.upper()}_Y = {y:.1f}f')
out.append('}')
open(f'{P}/wakil/app/src/main/java/com/wakil/agent/ui/components/RigData.kt','w').write('\n'.join(out)+'\n')
print('\n'.join(out))
